import '../Model/cart.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';class CartSources {  static Future<CartModel> getCarts() async {    final response = await DioHelper.getData(      path: ApiEndpoints.cart,    );    final data = CartModel.fromJson(response.data["data"]);    return data;  } static Future<CartModel> removeFromCart({required int id}) async {    final response = await DioHelper.deleteData(      path: "${ApiEndpoints.removeCart}/$id",    );    final data = CartModel.fromJson(response.data["data"]);    return data;  } static Future<bool> clearCart() async {    final response = await DioHelper.postData(      path: ApiEndpoints.clearCart,    );    // final data = CartItemsModel.fromJson(response.data["data"]);    return response.statusCode == 200 ? true : false;  }  static Future<CartModel> updateFromCart(      {required int id, required int newQuantity}) async {    final response = await DioHelper.putData(      data: {"quantity": newQuantity},      path: "${ApiEndpoints.updateCart}/$id",    );    final data = CartModel.fromJson(response.data["data"]);    return data;  }  //* Coupons  static Future<CartModel> applyCoupon({required String code}) async {    final response = await DioHelper.postData(      data: {"code": code},      path: ApiEndpoints.applyCoupon,    );      final data = CartModel.fromJson(response.data["data"]);    return data;  }  static  Future<CartModel> removeCoupon({required String code}) async {    final response = await DioHelper.postData(      data: {"code": code},      path: ApiEndpoints.removeCoupon,    );    final data = CartModel.fromJson(response.data["data"]);    return data;  }}